{#- Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/feature-rows.json
    The features as rows: text beside a picture (the rows layout of FeatureGrid). Icons are Lucide names.
    Props (p): features, mediaSide. -#}
{%- set v_features = og_def(p['features'], none) -%}
{%- set v_mediaSide = og_def(p['mediaSide'], 'end') -%}
{%- set c_6 -%}
  {%- for v_feature in og_l(v_features) %}
    {%- set c_5 -%}
      {%- set c_3 -%}
        {{ og_include('icons/lucide-icon.html.j2', {'p': {'Name': og_s(og_get(v_feature, ['icon'])), 'Size': 24}}) }}
        {%- set c_1 -%}
          {{ og_text(og_get(v_feature, ['title'])) }}
        {%- endset -%}
        {{ og_include('compose/title.html.j2', {'p': {'As': 3, 'Size': 'xl', 'Weight': 'bold'}, 'children': c_1}) }}
        {%- set c_2 -%}
          {{ og_text(og_get(v_feature, ['text'])) }}
        {%- endset -%}
        {{ og_include('compose/text.html.j2', {'p': {'Size': 'base', 'Class': 'text-muted-foreground'}, 'children': c_2}) }}
      {%- endset -%}
      {{ og_include('compose/stack.html.j2', {'p': {'Gap': '2', 'Class': 'min-w-0'}, 'children': c_3}) }}
      {%- set c_4 -%}
        {{ og_include('blocks/media-frame.html.j2', {'p': {'alt': og_get(v_feature, ['title']), 'ratio': '4/3'}}) }}
      {%- endset -%}
      {{ og_include('compose/box.html.j2', {'p': {'Class': og_s(og_cnv(['w-full min-w-0', ('md:order-first' if og_t(og_eq(v_mediaSide, 'start')) else ('md:group-even:order-first' if og_t(og_eq(v_mediaSide, 'alternate')) else ''))]))}, 'children': c_4}) }}
    {%- endset -%}
    {{ og_include('compose/grid.html.j2', {'p': {'Cols': '1-2', 'Class': 'group items-center gap-8', 'Attrs': og_attrs(['data-slot', 'feature-card'])}, 'children': c_5}) }}
  {%- endfor %}
{%- endset -%}
{{ og_include('compose/stack.html.j2', {'p': {'Gap': '8', 'Align': 'stretch', 'Attrs': og_attrs(['data-slot', 'feature-rows'])}, 'children': c_6}) }}
